import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { list_Directory_forms } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { format_Date } from "@/JsonFiles/DateFormate.js";
import RequestDirectoryAccess from "@/components/LookitUPDirectiory/AllDialogs/RequestDirectoryAccess.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    RequestDirectoryAccess,
    SnackBar
  },
  mixins: [get_all_org_users],
  data() {
    return {
      headers: [{
        title: "Name",
        key: "directory_name",
        sortable: false
      }, {
        title: "Description",
        key: "directory_description",
        sortable: false
      }, {
        title: "#Entries",
        key: "directory_entries",
        sortable: false
      }, {
        title: "#Subs",
        key: "directory_subscriber_count",
        sortable: false
      }, {
        title: "Created On",
        key: "directory_created_on",
        sortable: false
      }, {
        title: "Created By",
        key: "directory_created_by",
        sortable: false
      }, {
        title: "Actions",
        key: "Actions",
        sortable: false
      }],
      tableData: [],
      searchQuery: "",
      tableLoading: false,
      allusers: [],
      componentCheck: 0,
      requestAccessDialog: false,
      rowInfo: {},
      SnackBarComponent: {},
      currentPage: 1,
      itemsPerPage: 20,
      windowHeight: 0
    };
  },
  async created() {
    this.windowHeight = window.innerHeight - 260;
    this.fetch_all_directories();
    await this.get_all_org_users();
    this.allusers = this.orgUsers;
  },
  computed: {
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.tableData;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.tableData.filter(directory => directory.directory_name?.toLowerCase().includes(searchTerm) || directory.directory_description?.toLowerCase().includes(searchTerm) || this.fethc_names(directory.directory_created_by)?.toLowerCase().includes(searchTerm));
    },
    totalCount() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.filteredItems.length / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.filteredItems.slice(start, end);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
    currentPage() {
      // Scroll to top when page changes
      const table = document.querySelector(".modern-data-table");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  methods: {
    async fetch_all_directories() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_Directory_forms, {
          input: {
            organization_id: data.organization.organization_id
          }
        }));
        this.tableLoading = false;
        this.tableData = [];
        var response = JSON.parse(result.data.list_Directory_forms);
        let restrictedDirectories = [];
        let arraynew = [];
        if (response.Status == "SUCCESS") {
          restrictedDirectories = response.data;
          restrictedDirectories.forEach(element => {
            if (element.directory_visibility_type == "USERS" && element.directory_created_by != this.$store.getters.GetUserObj.user.user_email_id) {
              arraynew.push(element);
              this.tableData = arraynew.filter(item => !item.directory_visibility_users.includes(this.$store.getters.GetUserObj.user.user_id));
            }
          });
        }
      } catch (error) {
        this.tableLoading = false;
      }
    },
    request_access(item) {
      this.rowInfo = item;
      this.componentCheck = 1;
      this.requestAccessDialog = true;
    },
    get_successs_toast(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.requestAccessDialog = false;
    },
    get_error(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    fethc_names(value) {
      var name = "";
      this.orgUsers.forEach(element => {
        if (element.user_email_id == value) {
          name = element.full_user_name;
        }
      });
      return name;
    },
    get_date(val) {
      return format_Date(val);
    }
  }
};
